-- School-scoped Tier 1 talents: replace class scoping with a school scope.
--
-- Phase 1d Tier 1. These talents use an op that has a per-school aura lever, so
-- 'your Scorch, Fireball and Frostfire Bolt crit 3% more' becomes 'your Fire and
-- Frost spells crit 3% more' - which the character's second class can use too.
--
-- Op -> aura (each verified against this core's consumer, not guessed):
--   DAMAGE / DOT           -> 79  MOD_DAMAGE_PERCENT_DONE      (school mask)
--   CRITICAL_CHANCE        -> 71  MOD_SPELL_CRIT_CHANCE_SCHOOL (school mask)
--   CRIT_DAMAGE_BONUS      -> 163 MOD_CRIT_DAMAGE_BONUS        (school mask)
--   RESIST_MISS_CHANCE     -> 199 MOD_INCREASES_SPELL_PCT_TO_HIT (school mask)
--   COST flat              -> 73  MOD_POWER_COST_SCHOOL        (school mask)
--   COST pct               -> 72  MOD_POWER_COST_SCHOOL_PCT    (school mask)
-- THREAT is excluded: its aura is consumed as a multiplier while the spellmod is
-- additive, so the magnitude needs a conversion that has not been verified.
--
-- Each rewritten slot keeps Effect_N (APPLY_AURA) and gets the new aura, the school
-- in EffectMiscValue_N and the same magnitude (the DBC's value-1 convention is
-- reapplied). Slots that merge onto one (aura, school) pair are blanked, because
-- the engine multiplies matching auras. SpellClassSet and the classmask stay in
-- place: none of these auras consult them, and they document the original scope.
--
-- Schools come from Blizzard's own wording (the spells named in each tooltip, else a
-- school named in it); the classmask cannot supply them - see the tool's docstring.
-- Chains whose tooltip names no spell or school are NOT converted, and
-- python3 tools/school_scope_tier1.py --report lists them as review items.
--
-- 283 spells. Read from Spell.dbc: /tmp/Spell.dbc
-- To revert: delete these ids from spell_dbc (the DELETE below lists them).

DELETE FROM `spell_dbc` WHERE `ID` IN (11095, 11108, 11124, 11180, 11190, 11207, 11222, 11242, 12282, 12290, 12308, 12349, 12350, 12378, 12398, 12399, 12400, 12467, 12469, 12489, 12490, 12663, 12664, 12672, 12810, 12811, 12839, 12840, 12872, 12873, 12963, 13732, 13733, 13863, 13865, 13866, 14057, 14072, 14079, 14080, 14082, 14083, 14128, 14132, 14135, 14136, 14137, 14162, 14163, 14164, 14168, 14169, 14171, 14172, 14173, 14910, 15047, 15259, 15275, 15307, 15308, 15309, 15310, 15317, 16035, 16038, 16039, 16041, 16089, 16105, 16106, 16107, 16108, 16109, 16110, 16111, 16112, 16160, 16161, 16173, 16222, 16223, 16224, 16225, 16493, 16494, 16821, 16822, 16833, 16834, 16835, 16896, 16897, 16899, 16909, 16910, 16911, 16912, 16913, 16934, 16935, 16936, 16937, 16938, 16947, 16948, 16949, 16966, 16968, 17793, 17796, 17801, 17802, 17803, 17810, 17811, 17812, 17813, 17814, 17815, 17833, 17834, 17927, 17929, 17930, 18119, 18120, 18427, 18428, 18429, 18459, 18460, 18827, 18829, 19159, 19160, 19416, 19417, 19418, 19419, 19420, 19454, 19455, 19456, 19461, 19462, 19485, 19487, 19488, 19489, 19490, 20224, 20225, 20330, 20331, 20332, 20502, 20503, 24691, 28592, 28593, 29721, 29776, 29787, 29790, 29792, 31124, 31126, 31234, 31235, 31236, 31569, 31570, 31879, 31880, 31881, 32043, 32477, 32483, 32484, 32601, 33167, 33171, 33172, 33213, 33214, 33215, 33221, 33222, 33223, 33224, 33225, 33371, 34455, 34459, 34460, 34485, 34486, 34487, 34488, 34489, 34494, 34496, 35396, 35397, 35578, 35581, 43338, 44449, 44469, 44470, 44471, 44472, 46951, 46952, 46953, 47266, 47267, 47268, 47269, 47270, 47294, 47295, 47296, 48492, 48494, 48495, 49013, 49137, 49188, 49657, 50685, 50686, 50687, 51480, 51481, 51482, 51632, 51633, 51708, 51709, 51710, 51711, 51712, 53241, 53243, 53244, 53245, 53246, 53302, 53303, 53304, 53486, 53488, 53671, 53673, 54151, 54154, 54155, 54637, 54638, 54639, 54734, 55236, 55237, 56822, 56927, 56929, 56930, 56931, 56932, 58435, 59057, 60184, 60185, 60187, 60188, 61330, 61331, 63108, 6